// ============================================================================
// SENT_apb: APB4 register wrapper around SENT_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/SENT.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/SENT.md
// ============================================================================
module SENT_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic sent_out,
  input logic sent_in
);
  localparam logic [31:0] ID_VALUE = 32'h4A320100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [15:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd16) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_cfg_crc_legacy;
  logic          c_tx_en;
  logic [11:0]   c_cfg_tx_tick_clks;
  logic [3:0]    c_cfg_tx_low_ticks;
  logic [2:0]    c_cfg_tx_nibbles;
  logic [1:0]    c_cfg_tx_pause_mode;
  logic [10:0]   c_cfg_tx_pause;
  logic [3:0]    c_tx_status;
  logic [23:0]   c_tx_data;
  logic          c_tx_frame_start;
  logic          c_ser_tx_start;
  logic          c_ser_tx_enh;
  logic          c_ser_tx_cfg;
  logic [7:0]    c_ser_tx_id;
  logic [15:0]   c_ser_tx_data;
  logic          c_ser_tx_busy;
  logic          c_ser_tx_done;
  logic [11:0]   c_cfg_rx_tick_clks;
  logic [2:0]    c_cfg_rx_nibbles;
  logic          c_cfg_rx_pause;
  logic          c_cfg_rx_cal_check;
  logic [3:0]    c_cfg_rx_filt;
  logic          c_rx_valid;
  logic [3:0]    c_rx_status;
  logic [23:0]   c_rx_data;
  logic [18:0]   c_rx_cal_clks;
  logic          c_rx_err_nibble;
  logic          c_rx_err_low;
  logic          c_rx_err_crc;
  logic          c_rx_err_pause;
  logic          c_rx_err_sync;
  logic          c_rx_err_cal;
  logic          c_ser_rx_valid;
  logic          c_ser_rx_enh;
  logic          c_ser_rx_cfg;
  logic [7:0]    c_ser_rx_id;
  logic [15:0]   c_ser_rx_data;
  logic          c_ser_rx_err_crc;
  SENT_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cfg_crc_legacy(c_cfg_crc_legacy),
    .tx_en(c_tx_en),
    .cfg_tx_tick_clks(c_cfg_tx_tick_clks),
    .cfg_tx_low_ticks(c_cfg_tx_low_ticks),
    .cfg_tx_nibbles(c_cfg_tx_nibbles),
    .cfg_tx_pause_mode(c_cfg_tx_pause_mode),
    .cfg_tx_pause(c_cfg_tx_pause),
    .tx_status(c_tx_status),
    .tx_data(c_tx_data),
    .tx_frame_start(c_tx_frame_start),
    .sent_out(sent_out),
    .ser_tx_start(c_ser_tx_start),
    .ser_tx_enh(c_ser_tx_enh),
    .ser_tx_cfg(c_ser_tx_cfg),
    .ser_tx_id(c_ser_tx_id),
    .ser_tx_data(c_ser_tx_data),
    .ser_tx_busy(c_ser_tx_busy),
    .ser_tx_done(c_ser_tx_done),
    .sent_in(sent_in),
    .cfg_rx_tick_clks(c_cfg_rx_tick_clks),
    .cfg_rx_nibbles(c_cfg_rx_nibbles),
    .cfg_rx_pause(c_cfg_rx_pause),
    .cfg_rx_cal_check(c_cfg_rx_cal_check),
    .cfg_rx_filt(c_cfg_rx_filt),
    .rx_valid(c_rx_valid),
    .rx_status(c_rx_status),
    .rx_data(c_rx_data),
    .rx_cal_clks(c_rx_cal_clks),
    .rx_err_nibble(c_rx_err_nibble),
    .rx_err_low(c_rx_err_low),
    .rx_err_crc(c_rx_err_crc),
    .rx_err_pause(c_rx_err_pause),
    .rx_err_sync(c_rx_err_sync),
    .rx_err_cal(c_rx_err_cal),
    .ser_rx_valid(c_ser_rx_valid),
    .ser_rx_enh(c_ser_rx_enh),
    .ser_rx_cfg(c_ser_rx_cfg),
    .ser_rx_id(c_ser_rx_id),
    .ser_rx_data(c_ser_rx_data),
    .ser_rx_err_crc(c_ser_rx_err_crc)
  );

  // ---------------- registers ----------------
  logic [12:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [3:0] r_CTRL;   // 12'h014 CTRL
  logic [20:0] r_TX_CFG;   // 12'h018 TX_CFG
  logic [10:0] r_TX_PAUSE;   // 12'h01C TX_PAUSE
  logic [27:0] r_TX_FRAME;   // 12'h020 TX_FRAME
  logic [25:0] r_SER_TX;   // 12'h024 SER_TX
  logic [0:0] p_CMD;   // 12'h028 CMD (pulses)
  logic [18:0] r_RX_CFG;   // 12'h02C RX_CFG
  logic [27:0] h_RX0;   // 12'h034 RX0 holding register
  logic [18:0] h_RX1;   // 12'h038 RX1 holding register
  logic [25:0] h_SER_RX;   // 12'h03C SER_RX holding register
  logic avail_RX;
  logic avail_SER_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 4'h0;
      r_TX_CFG <= 21'h65096;
      r_TX_PAUSE <= 11'h0;
      r_TX_FRAME <= 28'h0;
      r_SER_TX <= 26'h0;
      p_CMD <= '0;
      r_RX_CFG <= 19'h16096;
      h_RX0 <= '0;
      h_RX1 <= '0;
      h_SER_RX <= '0;
      avail_RX <= 1'b0;
      avail_SER_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[12:0] & wmask[12:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[12:0]) | (PWDATA[12:0] & wmask[12:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[6]) r_TX_CFG <= (r_TX_CFG & ~wmask[20:0]) | (PWDATA[20:0] & wmask[20:0]);
      if (wr && hit[7]) r_TX_PAUSE <= (r_TX_PAUSE & ~wmask[10:0]) | (PWDATA[10:0] & wmask[10:0]);
      if (wr && hit[8]) r_TX_FRAME <= (r_TX_FRAME & ~wmask[27:0]) | (PWDATA[27:0] & wmask[27:0]);
      if (wr && hit[9]) r_SER_TX <= (r_SER_TX & ~wmask[25:0]) | (PWDATA[25:0] & wmask[25:0]);
      p_CMD <= (wr && hit[10]) ? PWDATA[0:0] & wmask[0:0] : '0;
      if (wr && hit[11]) r_RX_CFG <= (r_RX_CFG & ~wmask[18:0]) | (PWDATA[18:0] & wmask[18:0]);
      if (c_rx_valid && (!avail_RX || (rd && hit[14]))) begin
        h_RX0[3:0] <= c_rx_status[3:0];
        h_RX0[27:4] <= c_rx_data[23:0];
        h_RX1[18:0] <= c_rx_cal_clks[18:0];
        avail_RX <= 1'b1;
      end else if (rd && hit[14]) avail_RX <= 1'b0;
      if (c_ser_rx_valid && (!avail_SER_RX || (rd && hit[15]))) begin
        h_SER_RX[0:0] <= c_ser_rx_enh;
        h_SER_RX[1:1] <= c_ser_rx_cfg;
        h_SER_RX[9:2] <= c_ser_rx_id[7:0];
        h_SER_RX[25:10] <= c_ser_rx_data[15:0];
        avail_SER_RX <= 1'b1;
      end else if (rd && hit[15]) avail_SER_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_tx_en = r_CTRL[0:0];
  assign c_cfg_crc_legacy = r_CTRL[1:1];
  assign c_cfg_rx_pause = r_CTRL[2:2];
  assign c_cfg_rx_cal_check = r_CTRL[3:3];
  assign c_cfg_tx_tick_clks = r_TX_CFG[11:0];
  assign c_cfg_tx_low_ticks = r_TX_CFG[15:12];
  assign c_cfg_tx_nibbles = r_TX_CFG[18:16];
  assign c_cfg_tx_pause_mode = r_TX_CFG[20:19];
  assign c_cfg_tx_pause = r_TX_PAUSE[10:0];
  assign c_tx_status = r_TX_FRAME[3:0];
  assign c_tx_data = r_TX_FRAME[27:4];
  assign c_ser_tx_id = r_SER_TX[7:0];
  assign c_ser_tx_data = r_SER_TX[23:8];
  assign c_ser_tx_enh = r_SER_TX[24:24];
  assign c_ser_tx_cfg = r_SER_TX[25:25];
  assign c_ser_tx_start = p_CMD;
  assign c_cfg_rx_tick_clks = r_RX_CFG[11:0];
  assign c_cfg_rx_nibbles = r_RX_CFG[14:12];
  assign c_cfg_rx_filt = r_RX_CFG[18:15];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_tx_frame_start;
    irq_set[1] = c_ser_tx_done;
    irq_set[2] = c_rx_err_nibble;
    irq_set[3] = c_rx_err_low;
    irq_set[4] = c_rx_err_crc;
    irq_set[5] = c_rx_err_pause;
    irq_set[6] = c_rx_err_sync;
    irq_set[7] = c_rx_err_cal;
    irq_set[8] = c_ser_rx_err_crc;
    irq_set[9] = c_rx_valid & (~avail_RX | (rd & hit[14]));
    irq_set[10] = c_rx_valid & avail_RX & ~(rd & hit[14]);
    irq_set[11] = c_ser_rx_valid & (~avail_SER_RX | (rd & hit[15]));
    irq_set[12] = c_ser_rx_valid & avail_SER_RX & ~(rd & hit[15]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_SER_RX, avail_RX};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(r_TX_CFG);
      10'd7: apb_rdata = 32'(r_TX_PAUSE);
      10'd8: apb_rdata = 32'(r_TX_FRAME);
      10'd9: apb_rdata = 32'(r_SER_TX);
      10'd11: apb_rdata = 32'(r_RX_CFG);
      10'd12: apb_rdata = 32'({c_ser_tx_busy});
      10'd13: apb_rdata = 32'(h_RX0);
      10'd14: apb_rdata = 32'(h_RX1);
      10'd15: apb_rdata = 32'(h_SER_RX);
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
